tricStatus.Unavailable),Is.True);Assert.That(score.Metrics.Count(x=>x.Basis==ScoreMetricBasis.Baseline&&x.Name.StartsWith("expectedPaydirtP50AbsoluteError.Baseline.")),Is.EqualTo(4));Assert.That(inputDocument.RootElement.GetProperty("artifacts").GetArrayLength(),Is.EqualTo(13));Assert.That(persisted.CanonicalInputJson,Does.Not.Contain("measuredDepthM").And.Not.Contain("oilSaturation").And.Not.Contain("monthlyTruth"));Assert.That(upstream.ScorecardBody!.Value.GetProperty("scoringModelVersion").GetString(),Is.EqualTo(ScoreArtifactIntegrity.ModelVersion));Assert.That(upstream.ScorecardBody.Value.EnumerateObject().Select(x=>x.Name),Is.EquivalentTo(new[]{"scorecardId","runId","revealId","scoringModelVersion","inputSha256","headlineMetric","metrics","createdValidTimeUtc"}));Assert.That(upstream.ScorecardCount,Is.EqualTo(1));Assert.That(effects,Is.EqualTo((1,1)));Assert.That(replayBody,Is.EqualTo(body));Assert.That(get,Does.Not.Contain("\\\"samples\\\":[").And.Not.Contain("measuredDepthM").And.Not.Contain("oilSaturation").And.Not.Contain("monthlyTruth").And.Not.Contain("worldId").And.Not.Contain("bindingId"));Assert.That(sse,Does.Contain("S9Score").And.Contain("Completed").And.Not.Contain("metric").And.Not.Contain("truth"));Assert.That(audit,Does.Not.Contain("measuredDepthM").And.Not.Contain("oilSaturation").And.Contain("scorecard.published"));});
  await using var connection=new SqliteConnection($"Data Source={factory.DatabasePath}");await connection.OpenAsync();await using var mutate=connection.CreateCommand();mutate.CommandText="UPDATE Scorecards SET InputSha256=$hash;";mutate.Parameters.AddWithValue("$hash",TestData.HashD);Assert.ThrowsAsync<SqliteException>(async()=>await mutate.ExecuteNonQueryAsync());await using var metric=connection.CreateCommand();metric.CommandText="UPDATE ScorecardMetrics SET Value=0;";Assert.ThrowsAsync<SqliteException>(async()=>await metric.ExecuteNonQueryAsync());await using var receiptMutation=connection.CreateCommand();receiptMutation.CommandText="UPDATE ScorecardReceipts SET ReceiptHash=$hash;";receiptMutation.Parameters.AddWithValue("$hash",TestData.HashD);Assert.ThrowsAsync<SqliteException>(async()=>await receiptMutation.ExecuteNonQueryAsync());var restarted=new DrillingOperationsStore($"Data Source={factory.DatabasePath}",TimeProvider.System);await restarted.InitializeAsync();Assert.That((await restarted.GetScorecardAsync(revealed.RunId))?.OutputSha256,Is.EqualTo(score.OutputSha256));await using var readReceipt=connection.CreateCommand();readReceipt.CommandText="SELECT CanonicalReceiptJson FROM ScorecardReceipts;";string originalReceipt=(string)(await readReceipt.ExecuteScalarAsync())!;await using var forceReceipt=connection.CreateCommand();forceReceipt.CommandText="DROP TRIGGER TR_ScorecardReceipts_NoUpdate;UPDATE ScorecardReceipts SET CanonicalReceiptJson='{}',ReceiptHash=$hash;";forceReceipt.Parameters.AddWithValue("$hash",DeterministicIdentity.Sha256("{}"));await forceReceipt.ExecuteNonQueryAsync();Assert.ThrowsAsync<PersistenceIntegrityException>(async()=>await restarted.GetScorecardAsync(revealed.RunId));await using var restoreReceipt=connection.CreateCommand();restoreReceipt.CommandText="UPDATE ScorecardReceipts SET CanonicalReceiptJson=$json,ReceiptHash=$hash;";restoreReceipt.Parameters.AddWithValue("$json",originalReceipt);restoreReceipt.Parameters.AddWithValue("$hash",DeterministicIdentity.Sha256(originalReceipt));await restoreReceipt.ExecuteNonQueryAsync();Assert.That((await restarted.GetScorecardAsync(revealed.RunId))?.ScorecardId,Is.EqualTo(score.ScorecardId));await using var drop=connection.CreateCommand();drop.CommandText="DROP TRIGGER TR_ScorecardMetrics_NoUpdate;UPDATE ScorecardMetrics SET ContentSha256=$hash WHERE Sequence=0;";drop.Parameters.AddWithValue("$hash",TestData.HashD);await drop.ExecuteNonQueryAsync();Assert.ThrowsAsync<PersistenceIntegrityException>(async()=>await restarted.GetScorecardAsync(revealed.RunId));
