 [Test]
 public async Task LegacyMetricContractFailure_IsRepairedOnce_AndRetriesPersistedCallback()
 {
  var fixture=PredictionFixture.Create();var upstream=new PublicationFakeHandler{ScorecardMismatch=true};await using var factory=new ApiFactory(fixture.Respond,publication:upstream);using var client=factory.CreateInternalClient();RunResponse revealed=await ReadyRevealed(client,fixture.SealHash);Assert.That((await Score(client,revealed.RunId,"legacy-contract-failure")).StatusCode,Is.EqualTo(HttpStatusCode.Conflict));var store=factory.Services.GetRequiredService<DrillingOperationsStore>();ScorecardDraft original=(await store.GetScoringCheckpointAsync(revealed.RunId))!;string legacyOutputHash=await RewriteAsLegacyScorecardAsync(factory.DatabasePath,original);
  var restarted=new DrillingOperationsStore($"Data Source={factory.DatabasePath}",TimeProvider.System);await restarted.InitializeAsync();RunResponse repairedRun=(await restarted.GetRunAsync(revealed.RunId))!;ScorecardDraft repaired=(await restarted.GetScoringCheckpointAsync(revealed.RunId))!;StageResponse s9=(await restarted.GetStagesAsync(revealed.RunId)).Single(x=>x.Stage==RunStageKind.S9Score);IReadOnlyList<AuditResponse> audit=await restarted.GetAuditAsync(TestData.ScenarioId);Assert.Multiple(()=>{Assert.That(repairedRun.Status,Is.EqualTo(RunStatus.AwaitingDependency));Assert.That(s9.Status,Is.EqualTo(StageStatus.AwaitingDependency));Assert.That(s9.DiagnosticCode,Is.EqualTo("ScorecardContractRepaired"));Assert.That(repaired.ScorecardId,Is.EqualTo(original.ScorecardId));Assert.That(repaired.InputSha256,Is.EqualTo(original.InputSha256));Assert.That(repaired.OutputSha256,Is.Not.EqualTo(legacyOutputHash));Assert.That(repaired.Metrics.Count(x=>x.Name.Contains("ScoredMonthCount",StringComparison.Ordinal)),Is.EqualTo(6));Assert.That(repaired.Metrics.Where(x=>x.Status==ScoreMetricStatus.Scored).All(x=>x.Limitation is null),Is.True);Assert.That(audit.Count(x=>x.Action=="scorecard.contract-repaired"),Is.EqualTo(1));});
  await restarted.InitializeAsync();IReadOnlyList<AuditResponse> restartedAudit=await restarted.GetAuditAsync(TestData.ScenarioId);Assert.That(restartedAudit.Count(x=>x.Action=="scorecard.contract-repaired"),Is.EqualTo(1));upstream.ScorecardMismatch=false;fixture.CorruptPrediction=true;HttpResponseMessage response=await Score(client,revealed.RunId,"legacy-contract-retry");Assert.That(response.StatusCode,Is.EqualTo(HttpStatusCode.OK));RunResponse scored=(await store.GetRunAsync(revealed.RunId))!;Assert.Multiple(()=>{Assert.That(upstream.ScorecardCount,Is.EqualTo(2));Assert.That(scored.Status,Is.EqualTo(RunStatus.Scored));});
 }
