 {
  var fixture=PredictionFixture.Create();var upstream=new PublicationFakeHandler{ScorecardMismatch=true};await using var factory=new ApiFactory(fixture.Respond,publication:upstream);using var client=factory.CreateInternalClient();RunResponse revealed=await ReadyRevealed(client,fixture.SealHash);Assert.That((await Score(client,revealed.RunId,"legacy-unsafe-"+variant)).StatusCode,Is.EqualTo(HttpStatusCode.Conflict));ScorecardDraft card=(await factory.Services.GetRequiredService<DrillingOperationsStore>().GetScoringCheckpointAsync(revealed.RunId))!;await RewriteAsLegacyScorecardAsync(factory.DatabasePath,card);await using(var connection=new SqliteConnection($"Data Source={factory.DatabasePath}")){await connection.OpenAsync();await using var mutation=connection.CreateCommand();mutation.CommandText=variant switch{"side-effect-count"=>"UPDATE Runs SET PublicationCount=0 WHERE RunId=$run;","receipt"=>"INSERT INTO ScorecardReceipts(ScorecardId,CanonicalReceiptJson,ReceiptHash,ReceivedUtc)VALUES($card,'{}',$hash,$now);","metric-hash"=>"UPDATE ScorecardMetrics SET ContentSha256=$hash WHERE ScorecardId=$card AND Sequence=0;","diagnostic"=>"UPDATE Runs SET DiagnosticCode='DifferentFailure' WHERE RunId=$run;",_=>throw new AssertionException("Unknown variant")};mutation.Parameters.AddWithValue("$run",revealed.RunId);mutation.Parameters.AddWithValue("$card",card.ScorecardId);mutation.Parameters.AddWithValue("$hash",DeterministicIdentity.Sha256("{}"));mutation.Parameters.AddWithValue("$now",DateTimeOffset.UtcNow.ToString("O"));await mutation.ExecuteNonQueryAsync();}
  var restarted=new DrillingOperationsStore($"Data Source={factory.DatabasePath}",TimeProvider.System);await restarted.InitializeAsync();RunResponse unchanged=(await restarted.GetRunAsync(revealed.RunId))!;IReadOnlyList<AuditResponse> audit=await restarted.GetAuditAsync(TestData.ScenarioId);Assert.Multiple(()=>{Assert.That(unchanged.Status,Is.EqualTo(RunStatus.Failed));Assert.That(audit.Any(x=>x.Action=="scorecard.contract-repaired"),Is.False);});
 }
