 [Test]
 public async Task HistoricalBoundsFailureRetainsExactCheckpointAndRemainsTerminalWithoutAutomaticRepair()
 {
  var prediction=PredictionFixture.Create();var upstream=new PublicationFakeHandler{ScorecardMismatch=true};
  await using var factory=new ApiFactory(prediction.Respond,publication:upstream);using var client=factory.CreateInternalClient();
  RunResponse revealed=await ReadyRevealed(client,prediction.SealHash);
  Assert.That((await Score(client,revealed.RunId,"historical-bounds-initial")).StatusCode,Is.EqualTo(HttpStatusCode.Conflict));
  var store=factory.Services.GetRequiredService<DrillingOperationsStore>();ScorecardDraft original=(await store.GetScoringCheckpointAsync(revealed.RunId))!;
  ScorecardMetric prior=original.Metrics[0],legacy=prior with{LowerBound=prior.Value+1,UpperBound=prior.Value+2};
  ScorecardMetric[] metrics=original.Metrics.Select((metric,index)=>index==0?legacy:metric).ToArray();
  var request=JsonSerializer.Deserialize<AnalysisScorecardRequest>(original.CanonicalOutputJson,CanonicalJson.SerializerOptions)! with{Metrics=metrics};
  string output=CanonicalJson.Serialize(request),outputHash=DeterministicIdentity.Sha256(output),metricJson=CanonicalJson.Serialize(legacy);
  await using(var c=new SqliteConnection($"Data Source={factory.DatabasePath}"))
  {
   await c.OpenAsync();await using var tx=c.BeginTransaction(false);await using var q=c.CreateCommand();q.Transaction=tx;
   q.CommandText="""
    DROP TRIGGER TR_Scorecards_NoUpdate;
    DROP TRIGGER TR_ScorecardMetrics_NoUpdate;
    UPDATE Scorecards SET CanonicalOutputJson=$output,OutputSha256=$outputHash WHERE ScorecardId=$card;
    UPDATE ScorecardMetrics SET LowerBound=$lower,UpperBound=$upper,CanonicalJson=$metric,ContentSha256=$metricHash WHERE ScorecardId=$card AND Sequence=0;
    UPDATE RunStages SET OutputHash=$outputHash WHERE RunId=$run AND Stage=9;
    """;
   q.Parameters.AddWithValue("$output",output);q.Parameters.AddWithValue("$outputHash",outputHash);
   q.Parameters.AddWithValue("$card",original.ScorecardId);q.Parameters.AddWithValue("$run",original.RunId);
   q.Parameters.AddWithValue("$lower",legacy.LowerBound!);q.Parameters.AddWithValue("$upper",legacy.UpperBound!);
   q.Parameters.AddWithValue("$metric",metricJson);q.Parameters.AddWithValue("$metricHash",DeterministicIdentity.Sha256(metricJson));
   await q.ExecuteNonQueryAsync();await tx.CommitAsync();
  }
  var restarted=new DrillingOperationsStore($"Data Source={factory.DatabasePath}",TimeProvider.System);await restarted.InitializeAsync();
  ScorecardDraft saved=(await restarted.GetScoringCheckpointAsync(revealed.RunId))!;
  Assert.Multiple(()=>
  {
   Assert.That(saved.CanonicalInputJson,Is.EqualTo(original.CanonicalInputJson));
   Assert.That(saved.InputSha256,Is.EqualTo(original.InputSha256));
   Assert.That(saved.CanonicalOutputJson,Is.EqualTo(output));
   Assert.That(saved.OutputSha256,Is.EqualTo(outputHash));
  });
  upstream.ScorecardMismatch=false;
  Assert.That((await Score(client,revealed.RunId,"historical-bounds-new-key")).StatusCode,Is.EqualTo(HttpStatusCode.Conflict));
  Assert.That((await restarted.GetRunAsync(revealed.RunId))!.Status,Is.EqualTo(RunStatus.Failed));
  Assert.That((await restarted.GetScoringCheckpointAsync(revealed.RunId))!.OutputSha256,Is.EqualTo(outputHash));
  Assert.That(upstream.ScorecardCount,Is.EqualTo(1));
  Assert.That(await restarted.GetSideEffectCountsAsync(revealed.RunId),Is.EqualTo((1,1)));
 }
 static async Task<string> RewriteAsLegacyScorecardAsync(string databasePath,ScorecardDraft card)
 {
  var counts=card.Metrics.Where(x=>x.Name.Contains("ScoredMonthCount",StringComparison.Ordinal)).ToDictionary(x=>(Phase(x.Name),x.Basis),x=>(int)x.Value!.Value);var legacy=new List<ScorecardMetric>();foreach(ScorecardMetric metric in card.Metrics){if(metric.Name.Contains("ScoredMonthCount",StringComparison.Ordinal))continue;string? limitation=null;if(metric.Status==ScoreMetricStatus.Scored){string? phase=TryPhase(metric.Name);if(phase is not null&&metric.Basis is ScoreMetricBasis.HiddenTruth or ScoreMetricBasis.RevealedObservation&&(metric.Name.StartsWith("monthly",StringComparison.Ordinal)||metric.Name.StartsWith("initial",StringComparison.Ordinal)&&metric.Basis==ScoreMetricBasis.RevealedObservation)){int count=counts[(phase,metric.Basis)];limitation=metric.Basis==ScoreMetricBasis.HiddenTruth?$"Scored {count} of 60 months; prediction checkpoints are linearly interpolated to monthly volumes.":$"Scored {count} of 60 months; null corrected months were excluded and prediction checkpoints were linearly interpolated.";}else if(metric.Name.StartsWith("expectedPaydirtP50AbsoluteError.Baseline.",StringComparison.Ordinal))limitation="Expected pay only.";else if(metric.Name=="expectedPaydirtAiMinusBestBaselineAbsoluteError.Baseline")limitation="Negative values indicate the approved prediction outperformed the best deterministic baseline.";}legacy.Add(metric.Status==ScoreMetricStatus.Scored?metric with{Limitation=limitation}:metric);}
  AnalysisScorecardRequest request=JsonSerializer.Deserialize<AnalysisScorecardRequest>(card.CanonicalOutputJson,CanonicalJson.SerializerOptions)! with{Metrics=legacy};string output=CanonicalJson.Serialize(request),hash=DeterministicIdentity.Sha256(output);await using var connection=new SqliteConnection($"Data Source={databasePath}");await connection.OpenAsync();await using var transaction=connection.BeginTransaction(false);await using(var drop=connection.CreateCommand()){drop.Transaction=transaction;drop.CommandText="DROP TRIGGER TR_Scorecards_NoUpdate;DROP TRIGGER TR_ScorecardMetrics_NoUpdate;DROP TRIGGER TR_ScorecardMetrics_NoDelete;";await drop.ExecuteNonQueryAsync();}await using(var delete=connection.CreateCommand()){delete.Transaction=transaction;delete.CommandText="DELETE FROM ScorecardMetrics WHERE ScorecardId=$card;";delete.Parameters.AddWithValue("$card",card.ScorecardId);await delete.ExecuteNonQueryAsync();}for(int i=0;i<legacy.Count;i++){ScorecardMetric metric=legacy[i];string json=CanonicalJson.Serialize(metric);await using var insert=connection.CreateCommand();insert.Transaction=transaction;insert.CommandText="INSERT INTO ScorecardMetrics(ScorecardId,Sequence,Name,Basis,Status,Value,Unit,LowerBound,UpperBound,Limitation,CanonicalJson,ContentSha256)VALUES($card,$sequence,$name,$basis,$status,$value,$unit,$lower,$upper,$limitation,$json,$hash);";insert.Parameters.AddWithValue("$card",card.ScorecardId);insert.Parameters.AddWithValue("$sequence",i);insert.Parameters.AddWithValue("$name",metric.Name);insert.Parameters.AddWithValue("$basis",metric.Basis.ToString());insert.Parameters.AddWithValue("$status",metric.Status.ToString());insert.Parameters.AddWithValue("$value",metric.Value??(object)DBNull.Value);insert.Parameters.AddWithValue("$unit",metric.Unit??(object)DBNull.Value);insert.Parameters.AddWithValue("$lower",metric.LowerBound??(object)DBNull.Value);insert.Parameters.AddWithValue("$upper",metric.UpperBound??(object)DBNull.Value);insert.Parameters.AddWithValue("$limitation",metric.Limitation??(object)DBNull.Value);insert.Parameters.AddWithValue("$json",json);insert.Parameters.AddWithValue("$hash",DeterministicIdentity.Sha256(json));await insert.ExecuteNonQueryAsync();}await using(var update=connection.CreateCommand()){update.Transaction=transaction;update.CommandText="UPDATE Scorecards SET CanonicalOutputJson=$output,OutputSha256=$hash WHERE ScorecardId=$card;UPDATE RunStages SET OutputHash=$hash,Diagnostics='ScorecardCallbackMismatch' WHERE RunId=$run AND Stage=9;UPDATE Runs SET DiagnosticCode='ScorecardCallbackMismatch' WHERE RunId=$run;UPDATE ScorecardDeliveries SET Diagnostic='ScorecardCallbackMismatch' WHERE ScorecardId=$card;";update.Parameters.AddWithValue("$output",output);update.Parameters.AddWithValue("$hash",hash);update.Parameters.AddWithValue("$card",card.ScorecardId);update.Parameters.AddWithValue("$run",card.RunId);await update.ExecuteNonQueryAsync();}await transaction.CommitAsync();return hash;
  static string Phase(string name)=>TryPhase(name)??throw new AssertionException("Month count phase missing.");static string? TryPhase(string name)=>new[]{"Oil","Gas","Water"}.SingleOrDefault(name.Contains);
 }
 internal static async Task<RunResponse> ReadyRevealed(HttpClient client,string hash){RunResponse ready=await ReadyRun(client,hash);using var publish=new HttpRequestMessage(HttpMethod.Post,$"/drillingoperations/api/runs/{ready.RunId}/publish");publish.Headers.Add("Idempotency-Key",Guid.NewGuid().ToString());(await client.SendAsync(publish)).EnsureSuccessStatusCode();return (await client.GetFromJsonAsync<RunResponse>($"/drillingoperations/api/runs/{ready.RunId}",CanonicalJson.SerializerOptions))!;}
 static async Task<RunResponse> ReadyRun(HttpClient client,string hash){var binding=TestData.Binding() with{ApprovedSealedPredictionHash=hash};using var bind=new HttpRequestMessage(HttpMethod.Post,$"/drillingoperations/api/scenarios/{TestData.ScenarioId}/bind"){Content=JsonContent.Create(binding)};bind.Headers.Add("Idempotency-Key",Guid.NewGuid().ToString());(await client.SendAsync(bind)).EnsureSuccessStatusCode();using var create=new HttpRequestMessage(HttpMethod.Post,"/drillingoperations/api/runs"){Content=JsonContent.Create(TestData.Run() with{ApprovedSealedPredictionHash=hash})};create.Headers.Add("Idempotency-Key",Guid.NewGuid().ToString());using var created=await client.SendAsync(create);created.EnsureSuccessStatusCode();RunResponse run=(await created.Content.ReadFromJsonAsync<RunResponse>(CanonicalJson.SerializerOptions))!;run=await Wait(client,run.RunId,x=>x.Status==RunStatus.AwaitingApproval);using var approve=new HttpRequestMessage(HttpMethod.Post,$"/drillingoperations/api/runs/{run.RunId}/completion/approve");approve.Headers.Add("Idempotency-Key",Guid.NewGuid().ToString());approve.Headers.Add("X-DrillSim-Human-Actor","scorer");(await client.SendAsync(approve)).EnsureSuccessStatusCode();return await Wait(client,run.RunId,x=>x.Status==RunStatus.ReadyToReveal);}
 static async Task<RunResponse> Wait(HttpClient client,string runId,Func<RunResponse,bool> done){for(int i=0;i<500;i++){RunResponse value=(await client.GetFromJsonAsync<RunResponse>($"/drillingoperations/api/runs/{runId}",CanonicalJson.SerializerOptions))!;if(done(value))return value;await Task.Delay(20);}throw new AssertionException("Run timeout.");}
 static async Task<HttpResponseMessage> Score(HttpClient client,string runId,string key){using var request=new HttpRequestMessage(HttpMethod.Post,$"/drillingoperations/api/runs/{runId}/score");request.Headers.Add("Idempotency-Key",key);return await client.SendAsync(request);}
 internal sealed class PredictionFixture
 {
